import os, json, subprocess, textwrap, sys, datetime

owner_repo = 'cli/cli'
start = '2024-12-01T00:00:00Z'
end = '2024-12-31T23:59:59Z'

# Helper to call gh api graphql

def gh_graphql(query, variables=None):
    cmd = ['gh','api','graphql','-f',f'query={query}']
    if variables:
        for k,v in variables.items():
            cmd.extend(['-f', f'{k}={v}'])
    result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    if result.returncode != 0:
        print(result.stderr, file=sys.stderr)
        raise SystemExit(1)
    return json.loads(result.stdout)

# Fetch PRs created in date range
pr_query = textwrap.dedent('''
query($search:String!, $after:String) {
  search(type: ISSUE, query: $search, first: 100, after: $after) {
    pageInfo { hasNextPage endCursor }
    nodes {
      ... on PullRequest {
        number
        createdAt
        mergedAt
        closedAt
        state
        author { login }
      }
    }
  }
}
''')

pr_search = f'repo:{owner_repo} is:pr created:{start.split("T")[0]}..{end.split("T")[0]}'

prs = []
cur = None
while True:
    data = gh_graphql(pr_query, {'search': pr_search, 'after': cur})
    nodes = data['data']['search']['nodes']
    prs.extend([n for n in nodes if n])
    page = data['data']['search']['pageInfo']
    if not page['hasNextPage']:
        break
    cur = page['endCursor']

# Fetch issues created in date range
issue_query = textwrap.dedent('''
query($search:String!, $after:String) {
  search(type: ISSUE, query: $search, first: 100, after: $after) {
    pageInfo { hasNextPage endCursor }
    nodes {
      ... on Issue {
        number
        createdAt
        closedAt
        state
        labels(first: 100) { nodes { name } }
      }
    }
  }
}
''')

issue_search = f'repo:{owner_repo} is:issue created:{start.split("T")[0]}..{end.split("T")[0]}'
issues = []
cur = None
while True:
    data = gh_graphql(issue_query, {'search': issue_search, 'after': cur})
    nodes = data['data']['search']['nodes']
    issues.extend([n for n in nodes if n])
    page = data['data']['search']['pageInfo']
    if not page['hasNextPage']:
        break
    cur = page['endCursor']

# Fetch issues closed in date range (for resolved bugs)
closed_issue_search = f'repo:{owner_repo} is:issue closed:{start.split("T")[0]}..{end.split("T")[0]}'
closed_issues = []
cur = None
while True:
    data = gh_graphql(issue_query, {'search': closed_issue_search, 'after': cur})
    nodes = data['data']['search']['nodes']
    closed_issues.extend([n for n in nodes if n])
    page = data['data']['search']['pageInfo']
    if not page['hasNextPage']:
        break
    cur = page['endCursor']

# Compute PR stats
from collections import Counter

def parse_dt(s):
    return datetime.datetime.fromisoformat(s.replace('Z','+00:00'))

pr_total = len(prs)
pr_merged = sum(1 for pr in prs if pr.get('mergedAt'))
pr_closed = sum(1 for pr in prs if pr.get('state') == 'CLOSED')

merge_days = []
for pr in prs:
    if pr.get('mergedAt'):
        created = parse_dt(pr['createdAt'])
        merged = parse_dt(pr['mergedAt'])
        merge_days.append((merged - created).total_seconds()/86400)

avg_merge_days = round(sum(merge_days)/len(merge_days), 1) if merge_days else 0.0

authors = [pr['author']['login'] if pr.get('author') else 'ghost' for pr in prs]
if authors:
    top_contributor = Counter(authors).most_common(1)[0][0]
else:
    top_contributor = ''

# Issue stats

def has_bug_label(issue):
    labels = issue.get('labels', {}).get('nodes', [])
    for lab in labels:
        name = lab.get('name','')
        if 'bug' in name.lower():
            return True
    return False

issue_total = len(issues)
issue_bug = sum(1 for i in issues if has_bug_label(i))
resolved_bugs = sum(1 for i in closed_issues if has_bug_label(i))

report = {
    'pr': {
        'total': pr_total,
        'merged': pr_merged,
        'closed': pr_closed,
        'avg_merge_days': float(f"{avg_merge_days:.1f}"),
        'top_contributor': top_contributor,
    },
    'issue': {
        'total': issue_total,
        'bug': issue_bug,
        'resolved_bugs': resolved_bugs,
    }
}

print(json.dumps(report, indent=2))

# write report.json
with open('/app/report.json', 'w', encoding='utf-8') as f:
    json.dump(report, f, indent=2)
    f.write('\n')
